"""Generate the browser lookup from the single maintained page-map JSON."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[2]
data=json.loads((root/'revision/h446/guides/paper-1-page-map.json').read_text())
script="""'use strict';
// Generated by tools/revision/build_guide_links.py. Edit the source page-map JSON.
// Keys identify pages in the pre-reorder edition; quiz banks retain those stable keys.
(function(){
 const pages=PAGE_MAP;
 const edition=EDITION;
 const file='/revision/h446/guides/H446_Paper_1_CORRECTED_DRAFT_2026-10-21.pdf';
 function pageNumber(key){const page=pages[String(key)];if(!Number.isInteger(page))throw new RangeError('Unknown Paper 1 guide key: '+key);return page;}
 function paper1(key){return file+'?v='+edition+'#page='+pageNumber(key);}
 window.RHSC_GUIDE_LINKS=Object.freeze({edition,pageNumber,paper1});
})();
""".replace('PAGE_MAP',json.dumps(data['page_keys'],separators=(',',':'))).replace('EDITION',json.dumps(data['edition']))
(root/'revision/h446/guide-links.js').write_text(script)
